-- Sample data: some employees have no manager (top of hierarchy)
CREATE TABLE employees (
    emp_id INT PRIMARY KEY,
    name VARCHAR(50),
    manager_id INT
);

INSERT INTO employees VALUES
    (1, 'Alice', NULL),
    (2, 'Bob', 1),
    (3, 'Carol', 1);

-- WRONG: returns 0 rows because NULL = NULL is UNKNOWN
SELECT * FROM employees WHERE manager_id = NULL;

-- CORRECT: returns Alice
SELECT * FROM employees WHERE manager_id IS NULL;

-- CORRECT: returns Bob and Carol
SELECT * FROM employees WHERE manager_id IS NOT NULL;
